import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from google.cloud import monitoring_v3
from google.cloud.monitoring_v3.types import ListTimeSeriesRequest


class ManagedMetricsMonitor:
    def __init__(self, project_id: Optional[str] = None) -> None:
        self.project_id = project_id or os.environ["GOOGLE_CLOUD_PROJECT"]
        self.client = monitoring_v3.MetricServiceClient()
        self.project_name = f"projects/{self.project_id}"

    def query_metric_data(
        self,
        metric_type: str,
        minutes_back: int = 60,
        resource_type: Optional[str] = None,
        resource_labels: Optional[Dict[str, str]] = None,
        metric_labels: Optional[Dict[str, str]] = None,
        alignment_period_seconds: int = 60,
        per_series_aligner: str = "ALIGN_MEAN",
        cross_series_reducer: Optional[str] = None,
        group_by_fields: Optional[List[str]] = None,
        page_size: int = 100,
    ) -> List[Dict[str, Any]]:
        now = datetime.now(timezone.utc)
        start = now - timedelta(minutes=minutes_back)

        interval = monitoring_v3.TimeInterval(
            {
                "end_time": {"seconds": int(now.timestamp())},
                "start_time": {"seconds": int(start.timestamp())},
            }
        )

        filter_parts = [f'metric.type = "{metric_type}"']
        if resource_type:
            filter_parts.append(f'resource.type = "{resource_type}"')
        if resource_labels:
            for key, value in resource_labels.items():
                filter_parts.append(f'resource.labels.{key} = "{value}"')
        if metric_labels:
            for key, value in metric_labels.items():
                filter_parts.append(f'metric.labels.{key} = "{value}"')

        filter_str = " AND ".join(filter_parts)

        aggregation = monitoring_v3.Aggregation(
            alignment_period={"seconds": alignment_period_seconds},
            per_series_aligner=getattr(
                monitoring_v3.Aggregation.Aligner, per_series_aligner
            ),
        )

        if cross_series_reducer:
            aggregation.cross_series_reducer = getattr(
                monitoring_v3.Aggregation.Reducer, cross_series_reducer
            )
            if group_by_fields:
                aggregation.group_by_fields.extend(group_by_fields)

        request = ListTimeSeriesRequest(
            name=self.project_name,
            filter=filter_str,
            interval=interval,
            view=ListTimeSeriesRequest.TimeSeriesView.FULL,
            aggregation=aggregation,
            page_size=page_size,
        )

        results: List[Dict[str, Any]] = []
        for series in self.client.list_time_series(request=request):
            points = []
            for point in series.points:
                point_data: Dict[str, Any] = {
                    "interval_end": point.interval.end_time.isoformat(),
                    "interval_start": point.interval.start_time.isoformat(),
                }

                value = point.value
                if value.double_value is not None:
                    point_data["value"] = value.double_value
                elif value.int64_value is not None:
                    point_data["value"] = int(value.int64_value)
                elif value.bool_value is not None:
                    point_data["value"] = value.bool_value
                elif value.string_value:
                    point_data["value"] = value.string_value
                elif value.distribution_value:
                    point_data["value"] = {
                        "count": value.distribution_value.count,
                        "mean": value.distribution_value.mean,
                        "bucket_counts": list(value.distribution_value.bucket_counts),
                    }
                else:
                    point_data["value"] = None

                points.append(point_data)

            results.append(
                {
                    "metric_type": series.metric.type,
                    "metric_labels": dict(series.metric.labels),
                    "resource_type": series.resource.type,
                    "resource_labels": dict(series.resource.labels),
                    "points": points,
                    "unit": getattr(series, "unit", ""),
                }
            )

        return results


def query_metric_data(
    metric_type: str,
    minutes_back: int = 60,
    resource_type: Optional[str] = None,
    resource_labels: Optional[Dict[str, str]] = None,
    metric_labels: Optional[Dict[str, str]] = None,
    project_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    monitor = ManagedMetricsMonitor(project_id=project_id)
    return monitor.query_metric_data(
        metric_type=metric_type,
        minutes_back=minutes_back,
        resource_type=resource_type,
        resource_labels=resource_labels,
        metric_labels=metric_labels,
    )
